s "approval setup" ok "INSERT INTO Business (BusinessID,Name) VALUES ('B1','Cafe'); INSERT INTO Location (LocationID,BusinessID,Name,TimeZone) VALUES ('L1','B1','Main','America/Chicago'); INSERT INTO Role (RoleID,BusinessID,Name,OpensTo) VALUES ('RO1','B1','Manager','REGISTER'); INSERT INTO Employee (EmployeeID,BusinessID,FirstName,LastName,Email,EmployeeNumber,RoleID) VALUES ('E1','B1','A','A','e1@x.y','00000001','RO1');"
t "record a decision" ok "INSERT INTO ApprovalAction (ApprovalActionID,BusinessID,ActorEmployeeID,ApproverEmployeeID,LocationID,ActionType,TargetID,Payload) VALUES ('AA1','B1','E1','E1','L1','REFUND_REJECT','RF1','{}');"
a "the trigger queues it" "SELECT CONCAT(EntityName,'/',EntityID,'/',ActionType,'/',Status) FROM NotificationQueue" "ApprovalAction/AA1/REFUND_REJECT/Pending"
a "with the whole decision in the message" "SELECT CONCAT(NewData->>'$.actorId','/',NewData->>'$.approverId','/',NewData->>'$.targetId','/',NewData->>'$.locationId') FROM NotificationQueue" "E1/E1/RF1/L1"
t "the worker marks it done" ok "UPDATE NotificationQueue SET Status='Done', ProcessedAt=NOW() WHERE EntityID='AA1';"
t "or failed, with a reason" ok "UPDATE NotificationQueue SET Status='Failed', Error='nope' WHERE EntityID='AA1';"
